selector_to_html = {"a[href=\"#key-capabilities\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Key capabilities<a class=\"headerlink\" href=\"#key-capabilities\" title=\"Link to this heading\">#</a></h3><p><strong>Auto-wait and web-first assertions.</strong> No artificial timeouts. Playwright waits for elements to be actionable, and assertions automatically retry until conditions are met.</p><p><strong>Locators.</strong> Find elements with resilient locators that mirror how users see the page:</p>", "a[href=\"#cross-browser-support\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Cross-Browser Support<a class=\"headerlink\" href=\"#cross-browser-support\" title=\"Link to this heading\">#</a></h2><p>Headless and headed execution on all platforms. <sup>1</sup> Uses <a class=\"reference external\" href=\"https://developer.chrome.com/blog/chrome-for-testing\">Chrome for Testing</a> by default.</p>", "a[href=\"#how-it-works\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">How it works<a class=\"headerlink\" href=\"#how-it-works\" title=\"Link to this heading\">#</a></h3><p>Ask your AI assistant to interact with any web page:</p>", "a[href=\"#write-a-test\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Write a test<a class=\"headerlink\" href=\"#write-a-test\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#id2\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Install<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#session-monitoring\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Session monitoring<a class=\"headerlink\" href=\"#session-monitoring\" title=\"Link to this heading\">#</a></h3><p>Use <code class=\"docutils literal notranslate\"><span class=\"pre\">playwright-cli</span> <span class=\"pre\">show</span></code> to open a visual dashboard with live screencast previews of all running browser sessions. Click any session to zoom in and take remote control.</p>", "a[href=\"#usage\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Usage<a class=\"headerlink\" href=\"#usage\" title=\"Link to this heading\">#</a></h3><p>Point your coding agent at a task:</p>", "a[href=\"#resources\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Resources<a class=\"headerlink\" href=\"#resources\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#playwright-cli\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Playwright CLI<a class=\"headerlink\" href=\"#playwright-cli\" title=\"Link to this heading\">#</a></h2><p><a class=\"reference external\" href=\"https://github.com/microsoft/playwright-cli\">Playwright CLI</a> is a command-line interface for browser automation designed for coding agents. It\u2019s more token-efficient than MCP \u2014 commands avoid loading large tool schemas and accessibility trees into the model context.</p>", "a[href=\"#playwright-mcp\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Playwright MCP<a class=\"headerlink\" href=\"#playwright-mcp\" title=\"Link to this heading\">#</a></h2><p>The <a class=\"reference external\" href=\"https://github.com/microsoft/playwright-mcp\">Playwright MCP server</a> gives AI agents full browser control through the <a class=\"reference external\" href=\"https://modelcontextprotocol.io\">Model Context Protocol</a>. Agents interact with pages using structured accessibility snapshots \u2014 no vision models or screenshots required.</p>", "a[href=\"#documentation-api-reference\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><a class=\"reference external\" href=\"https://playwright.dev\">Documentation</a> | <a class=\"reference external\" href=\"https://playwright.dev/docs/api/class-playwright\">API reference</a><a class=\"headerlink\" href=\"#documentation-api-reference\" title=\"Link to this heading\">#</a></h2><p>Playwright is a framework for web automation and testing. It drives Chromium, Firefox, and WebKit with a single API \u2014 in your tests, in your scripts, and as a tool for AI agents.</p>", "a[href=\"#get-started\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Get Started<a class=\"headerlink\" href=\"#get-started\" title=\"Link to this heading\">#</a></h2><p>Choose the path that fits your workflow:</p>", "a[href=\"#examples\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Examples<a class=\"headerlink\" href=\"#examples\" title=\"Link to this heading\">#</a></h3><p><strong>Take a screenshot:</strong></p>", "a[href=\"#other-languages\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Other Languages<a class=\"headerlink\" href=\"#other-languages\" title=\"Link to this heading\">#</a></h2><p>Playwright is also available for <a class=\"reference external\" href=\"https://playwright.dev/python/docs/intro\">Python</a>, <a class=\"reference external\" href=\"https://playwright.dev/dotnet/docs/intro\">.NET</a>, and <a class=\"reference external\" href=\"https://playwright.dev/java/docs/intro\">Java</a>.</p>", "a[href=\"#id1\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Install<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h3><p>Optionally install skills for richer agent integration:</p>", "a[href=\"#playwright-library\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Playwright Library<a class=\"headerlink\" href=\"#playwright-library\" title=\"Link to this heading\">#</a></h2><p>Use <code class=\"docutils literal notranslate\"><span class=\"pre\">playwright</span></code> as a library for browser automation scripts \u2014 web scraping, PDF generation, screenshot capture, and any workflow that needs programmatic browser control without a test runner.</p>", "a[href=\"#playwright-test\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Playwright Test<a class=\"headerlink\" href=\"#playwright-test\" title=\"Link to this heading\">#</a></h2><p>Playwright Test is a full-featured test runner built for end-to-end testing. It runs tests across Chromium, Firefox, and WebKit with full browser isolation, auto-waiting, and web-first assertions.</p>", "a[href=\"#run-tests\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Run tests<a class=\"headerlink\" href=\"#run-tests\" title=\"Link to this heading\">#</a></h3><p>Tests run in parallel across all configured browsers, in headless mode by default. Each test gets a fresh browser context \u2014 full isolation with near-zero overhead.</p>", "a[href=\"#vs-code-extension\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">VS Code Extension<a class=\"headerlink\" href=\"#vs-code-extension\" title=\"Link to this heading\">#</a></h2><p>The <a class=\"reference external\" href=\"https://marketplace.visualstudio.com/items?itemName=ms-playwright.playwright\">Playwright VS Code extension</a> brings test running, debugging, and code generation directly into your editor.</p><p><strong>Run and debug tests</strong> from the editor with a single click. Set breakpoints, inspect variables, and step through test execution with a live browser view.</p>", "a[href=\"#setup\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Setup<a class=\"headerlink\" href=\"#setup\" title=\"Link to this heading\">#</a></h3><p>Add to your MCP client (VS Code, Cursor, Claude Desktop, Windsurf, etc.):</p>", "a[href=\"#playwright\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83c\udfad Playwright<a class=\"headerlink\" href=\"#playwright\" title=\"Link to this heading\">#</a></h1><p><a class=\"reference external\" href=\"https://www.npmjs.com/package/playwright\"><a data-lightbox=\"image-set\" href=\"https://img.shields.io/npm/v/playwright.svg\">\n<img alt=\"npm version\" src=\"https://img.shields.io/npm/v/playwright.svg\"/></a>\n</a> <!-- GEN:chromium-version-badge --><a class=\"reference external\" href=\"https://www.chromium.org/Home\"><a data-lightbox=\"image-set\" href=\"https://img.shields.io/badge/chromium-148.0.7778.96-blue.svg?logo=google-chrome\">\n<img alt=\"Chromium version\" src=\"https://img.shields.io/badge/chromium-148.0.7778.96-blue.svg?logo=google-chrome\"/></a>\n</a><!-- GEN:stop --> <!-- GEN:firefox-version-badge --><a class=\"reference external\" href=\"https://www.mozilla.org/en-US/firefox/new/\"><a data-lightbox=\"image-set\" href=\"https://img.shields.io/badge/firefox-150.0.2-blue.svg?logo=firefoxbrowser\">\n<img alt=\"Firefox version\" src=\"https://img.shields.io/badge/firefox-150.0.2-blue.svg?logo=firefoxbrowser\"/></a>\n</a><!-- GEN:stop --> <!-- GEN:webkit-version-badge --><a class=\"reference external\" href=\"https://webkit.org/\"><a data-lightbox=\"image-set\" href=\"https://img.shields.io/badge/webkit-26.4-blue.svg?logo=safari\">\n<img alt=\"WebKit version\" src=\"https://img.shields.io/badge/webkit-26.4-blue.svg?logo=safari\"/></a>\n</a><!-- GEN:stop --> <a class=\"reference external\" href=\"https://aka.ms/playwright/discord\"><a data-lightbox=\"image-set\" href=\"https://img.shields.io/badge/join-discord-informational\">\n<img alt=\"Join Discord\" src=\"https://img.shields.io/badge/join-discord-informational\"/></a>\n</a></p>", "a[href=\"#install\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Install<a class=\"headerlink\" href=\"#install\" title=\"Link to this heading\">#</a></h3><p>Or add manually:</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
